mapper.select:
SELECT id, point_mac as pointMac, create_time as createTime, lampblack_data as lampblackData, lampblack_avgdata as lampblackAvgdata, matter_data as matterData, nmhc_data as nmhcData, fan_status as fanStatus, purifier_status as purifierStatus, temp, hum FROM ${srcTable} WHERE 1=1
AND create_time >= #{startTime}
AND create_time < #{endTime}
ORDER BY create_time ASC, id ASC

SELECT bu_lampblack_id as buLampblackId, IFNULL(MAX(output_power),0) as maxPower, IFNULL(SUM(CASE WHEN output_power IS NOT NULL AND output_power > 0 THEN 1 ELSE 0 END),0) as onCnt, IFNULL(MAX(power_open_status),0) as maxOpen FROM ${srcTable} WHERE bu_lampblack_id IN
#{item}
GROUP BY bu_lampblack_id

mapper.delete:
DELETE FROM ai_predict_input
WHERE point_mac = #{pointMac}
  AND DATE_FORMAT(data_time,'%Y-%m-%d') = #{dataDate}

DELETE FROM ai_predict_input
WHERE 1=1

    AND data_time >= #{startTime}


    AND data_time < #{endTime}


    AND source_table = #{srcTable}

mapper.select:
SELECT point_mac as pointMac, company_id as companyId, DATE_FORMAT(data_time,'%Y-%m-%d') as statDate, COUNT(1) as slotCnt, SUM(CASE WHEN over_flag = 1 THEN 1 ELSE 0 END) as overSlotCnt, SUM(sample_cnt) as sampleCnt, SUM(over_cnt) as overCnt, IFNULL(ROUND(AVG(over_flag),6),0) as avgRate FROM ai_predict_input WHERE 1=1
AND DATE_FORMAT(data_time,'%Y-%m-%d') >= #{startDay}
AND DATE_FORMAT(data_time,'%Y-%m-%d') <= #{endDay}
AND source_table = #{srcTable}
GROUP BY point_mac, company_id, DATE_FORMAT(data_time,'%Y-%m-%d')

SELECT company_id as companyId, DATE_FORMAT(data_time,'%Y-%m-%d') as statDate, COUNT(1) as slotCnt, SUM(CASE WHEN over_flag = 1 THEN 1 ELSE 0 END) as overSlotCnt, SUM(sample_cnt) as sampleCnt, SUM(over_cnt) as overCnt FROM ai_predict_input WHERE company_id IS NOT NULL AND company_id != ''
AND DATE_FORMAT(data_time,'%Y-%m-%d') >= #{startDay}
AND DATE_FORMAT(data_time,'%Y-%m-%d') <= #{endDay}
AND source_table = #{srcTable}
GROUP BY company_id, DATE_FORMAT(data_time,'%Y-%m-%d')

SELECT point_mac as pointMac, company_id as companyId, DATE_FORMAT(data_time,'%Y-%m-%d') as statDate, MAX(over_flag) as overFlag FROM ai_predict_input WHERE 1=1
AND DATE_FORMAT(data_time,'%Y-%m-%d') >= #{startDay}
AND DATE_FORMAT(data_time,'%Y-%m-%d') <= #{endDay}
AND source_table = #{srcTable}
GROUP BY point_mac, company_id, DATE_FORMAT(data_time,'%Y-%m-%d')
